@scene(660, 20)
@duration(158)

// INVESTMENT CASTING A DRILL BIT ON A DIGITAL METAL TREE, in seventeen captioned steps.
//
// Each caption stays up long enough to read, about a second and fifteen characters a second,
// or until its step is nearly done; three seconds pass before the next. A step's own animation
// starts once its caption has been read and ends in the pause after it.
//
//   1  the bit, its carbide brazed on                10  the shell, coat by coat
//   2  the carbide and the braze taken off           11  the shell cut open, the print burned out
//   3  the casting turned shank up and moved out     12  the pour
//   4  a sprue: a cylinder, then the real one        13  the cooling, which takes the warp back out and cracks the shell
//   5  gates                                         14  the shell broken away
//   6  the warp simulated, then inverted             15  sawn; three parts and the sprue gone, the stubs ground
//   7  the tree: the branch patterned                16  shot peened, then back to where it began
//   8  the labels                                    17  the carbide brazed back on
//   9  the printed pattern: a lattice under a skin
//
// The tree is built with a copy of Digital Metal's libraries, as their tree
// documents build one: dm/sprue, dm/layout, dm/gate. One field, `tree`, is
// computed once at each point; every step is a cheap cut, offset, blend or
// threshold of it, and the heat and the finish are colour.
// All lengths in mm; the bit's own drawing is in inches.

@caption("A mining drill bit: tungsten carbide inserts\nbrazed to a cast steel body", 0.5, 6.5)
@caption("AI analyzes the body and develops a casting strategy", 9.5, 15)
@caption("We orient the body in the direction of the pour", 18, 22.5)
@caption("A sprue and pouring cup are added to supply the molten steel", 25.5, 30.5)
@caption("Gates join the part to the sprue to complete the branch", 33.5, 38.5)
@caption("We simulate the plastic deformation of the casting process and invert it", 41.5, 47.5)
@caption("The branch is patterned around the sprue, forming a tree", 50.5, 55.5)
@caption("The tree is embossed with its work order on top and alloy on the sides", 58.5, 64.5)
@caption("It is 3D printed as a pattern: a thin skin over a load bearing lattice", 67.5, 73.5)
@caption("The pattern is dipped in ceramic, coat after coat, to build a shell", 76.5, 82.5)
@caption("In the furnace, the pattern sublimates and the shell is fired", 85.5, 97)
@caption("~1,600°C Molten steel fills the hot shell", 100, 109.5)
@caption("The steel cools and shrinks to the warp-corrected size", 112.5, 117.5)
@caption("The shell easily breaks away", 120.5, 124.5)
@caption("The parts are sawn from the tree and their gates ground or machined off", 127.5, 134)
@caption("Shot peening evens and hardens the surface", 137, 141)
@caption("Finally, the carbide teeth are brazed on", 145.5, 154.5)

import "dm/sprue";
import "dm/layout";
import gate "dm/gate";

// ── The clock ──
// Seconds. captionAt is when each step's caption appears, as the captions above have it, and every
// animation is timed from its own step's caption: during(step, from, to) runs from `from` to `to`
// seconds after it. To retime a step, change its caption and its entry here; later steps keep their shape.
runSeconds = 158.0;
clock = time % runSeconds;
captionAt = [0.5, 9.5, 18, 25.5, 33.5, 41.5, 50.5, 58.5, 67.5, 76.5, 85.5, 100, 112.5, 120.5, 127.5, 137, 145.5];

// Every animation starts fast and settles: a quadratic ease out.
during(step, from, to) { return ease.outQuadratic(clamp((clock - captionAt[step - 1] - from) / (to - from), 0, 1)); }
after(step, seconds) { return clock > captionAt[step - 1] + seconds ? 1 : 0; }

unbrazed = during(2, 1.8, 2.8);
teethOff = during(2, 2.8, 5.2);
analysing = during(2, 2.8, 3.6) - during(2, 6.3, 7.3);
turned = during(3, 1.8, 5.8);
sprueIn = during(4, 2.0, 4.0);
cupped = during(4, 4.3, 6.3);
gatesIn = during(5, 2.0, 5.5);
simulated = during(6, 2.4, 4.4);
inverted = during(6, 5.0, 7.5);
labelled = during(8, 2.4, 3.9);
printing = after(9, 2.2);
printed = during(9, 2.4, 6.9);
coats = (during(10, 2.2, 3.0) + during(10, 3.3, 4.1) + during(10, 4.4, 5.2) + during(10, 5.5, 6.3) + during(10, 6.6, 7.4)) / 5;
sectioned = during(11, 2.2, 4.7);
burned = during(11, 4.7, 13.2);
poured = after(12, 1.4);
ladled = during(12, 1.6, 3.1);
filled = during(12, 3.4, 10.9);
rippling = during(12, 3.4, 4.4) - during(12, 10.4, 12.4);
cooled = during(13, 2.0, 6.5);
coolingSeconds = max(clock - captionAt[12] - 2.0, 0);   // since the steel began to cool
cracked = cooled;                    // the shell cannot follow the steel as its warp comes out, and cracks
shed = during(14, 1.4, 4.9);
sawn = during(15, 2.4, 3.9);
lifted = during(15, 4.2, 5.95);
ground = during(15, 4.4, 7.7);
peened = during(16, 1.6, 5.5);
returned = during(16, 5.8, 9.3);
teethOn = during(17, 1.6, 3.6);
torchSeconds = max(clock - captionAt[16] - 3.6, 0);     // since the torch came on
torched = during(17, 3.6, 4.4) * exp(-max(torchSeconds - 4.0, 0) / 2.5);   // on for four seconds, then the joint cools as the casting did
rebrazed = during(17, 5.4, 6.6);

// There are four branches from when the pattern begins until the other three have gone.
spread = after(7, 2.0) * (lifted < 0.995 ? 1 : 0);
fanned = during(7, 2.0, 6.0) * spread;
hero = 1 - turned + returned;

// The warp: +1 is the distortion the simulation predicts, -1 its inverse, which is cut into the
// pattern and stays until the steel cools and bends it back out.
warp = simulated - 2 * inverted + cooled;

// ── The tree, laid out as a Digital Metal tree document lays one out ──
// The sprue's cup is at the top, z = 5 to 65, and its shaft hangs below z = 0.
// Each branch is drawn along +x and hung at an angle and a drop from layout.
// There is one layer of branches, so the shaft stops level with the bits' tips.
verticalSpan = 176;
angles, heightsRaw = layout.fourSquare1(verticalSpan);
branchDrop = heightsRaw[0] + verticalSpan * 0.5;
sprueLength = verticalSpan;

// The branch: the bit hanging shank up at this radius, one gate into its
// shank and one into the wing that faces the sprue.
treeRadius = 112.0;
flangeZ = -5.0;                     // the underside of the bit's flange, in the branch's frame
gateSpread = 57.0;                  // the gates sit this far above and below the branch's z = 0
gateWidth = 20.0;
gateHeight = 26.0;
gatePenetration = 2.0;
stubLength = 6.0;                   // what the saw leaves on the wing; the shank's stub is longer
cutPlane = 54.0 - stubLength;       // where the saw crosses both gates
stubReach = 36.0;                   // how far the longer stub stands off the part
partScale = 1.016;                  // the pattern is 1.6% over size, for the steel's shrink as it cools

shellThickness = 8.0;
shellTop = sprue.coneStartZ + sprue.coneHeight * 0.75;   // the shell stops three quarters of the way up the cup
pourTop = shellTop - 2;
shardSize = 16.0;                   // the shell breaks into cells this size; the print burns out in cells half as big
treeLow = -190.0;
treeHigh = 70.0;

// The lower gate feeds a tooth that sits to one side of the branch. It leaves the sprue on its
// centre line and joggles over: the straight bar, sheared in y by a smooth step along its run
// from the shaft to the part. Dividing by the shear's slope keeps the field a distance.
lowerGateAt = [54, -14, -gateSpread];
joggleLength = lowerGateAt.x - sprue.shaftRadius;

lowerGate() {
  along = clamp((p.x - sprue.shaftRadius) / joggleLength, 0, 1);
  slope = lowerGateAt.y * 6 * along * (1 - along) / joggleLength;
  bar = remap(gate.horizontalRoundCentered(lowerGateAt, gateWidth, gateHeight, gatePenetration),
              [p.x, p.y - lowerGateAt.y * ease.quadratic(along), p.z]);
  return bar / sqrt(1 + slope * slope);
}

branchGates() {
  return unionSharp(
    gate.horizontalRoundCentered([79, 0, gateSpread], gateWidth, gateHeight, gatePenetration),
    lowerGate()
  );
}

// The copies fan out of the branch at the last of layout's angles, a quarter turn apart at the end.
fanStart = angles[3] - 2 * pi;
wedge = (angles[1] - angles[0]) * fanned;
firstCopy = -1;
fanCenter = (firstCopy + 1.5) * wedge;

// ── The camera's part: the viewer's is fixed, so the scene turns and the bit comes to it, at one scale throughout ──
// The tree is turned an eighth so the camera looks between two branches, and
// sits high in a roomy scene: the pour needs the space above it, the captions the space below.
treeCenter = [0, 0, -58];
heroAxis = [1, 1, 0];
heroAngle = radians(-150) * hero;
partCenter = [treeRadius, 0, flangeZ] * (1 - hero) + [0, 0, treeCenter.z + branchDrop] * hero;
shrink = 1 + (partScale - 1) * (turned - cooled);

// Each junk slot fillets into its wings: generously ahead of a cutting face, tightly behind a wing.
filletAhead = 0.50;
filletBehind = 0.20;

// Each insert's seat is cut with a rounded intersection, so its rim is broken to this radius,
// in inches. That leaves a groove along every seam between an insert and the steel, for the braze.
seatEdge = 0.04;

// The short wing runs out along +x with its cutting face on y = 0.
wingShort() {
  roof = max(
    dot(p, [-0.346, 0.383, -0.857]) - 2.259,
    dot(p, [0.316, 0.383, -0.868]) - 3.482,
    dot(p, [-0.265, 0.707, -0.656]) - 2.077,
    dot(p, [0.242, 0.707, -0.664]) - 3.013
  );
  slab = max(-p.y, p.y - 1.1, 0.94 - p.x, roof);
  seat = max(p.y - 0.25, p.z + 2.36);
  return intersectRound(slab, -seat, seatEdge);
}

// The long wing runs out along +y with its cutting face on x = 0.
wingLong() {
  roof = max(
    dot(p, [-0.383, -0.283, -0.879]) - 2.438,
    dot(p, [-0.383, 0.317, -0.868]) - 3.493,
    dot(p, [-0.707, -0.217, -0.673]) - 2.285,
    dot(p, [-0.707, 0.243, -0.664]) - 3.093
  );
  slab = max(p.x, -1.2 - p.x, 0.38 - p.y, roof);
  seat = max(-0.25 - p.x, p.z + 2.36);
  return intersectRound(slab, -seat, seatEdge);
}

blankInches() {
  r = length(p.xy);
  shortWing = wingShort();
  longWing = wingLong();
  pair = min(shortWing, longWing);
  pairFillet = mix(filletAhead, filletBehind, shortWing < longWing ? ramp(p.y, 0, 1.1, 0, 1) : ramp(-p.x, 0, 1.2, 0, 1));
  twin = remap(pair, [-p.x, -p.y, p.z]);
  prisms = min(pair, twin);
  filletRadius = pair < twin ? pairFillet : remap(pairFillet, [-p.x, -p.y, p.z]);
  envelope = max(r - 2.362, (r + p.z - 1.956) / sqrt2);
  wings = max(prisms, envelope);

  // Between the wings the body is a cone, and each junk slot fillets into it. The cone widens
  // upward, and it has to run on into the flange to join it. There it stops widening and
  // becomes a cylinder inside the flange: left as a cone, its flare came out past the flange in
  // every offset of the bit, as a sharp skirt round the collar of the shell.
  slotCone = (r - (1.885 + 0.4138 * p.z)) * 0.924;
  core = max((r - min(1.885 + 0.4138 * p.z, 1.9)) * 0.924, p.z - 0.3);
  fillets = max(unionRound(slotCone, prisms, filletRadius), envelope);
  slots = max(min(core, fillets), -1.45 - p.z);

  flange = cylinderCapped([0, 0, 0.021], [0, 0, 0.425], 1.935);
  shank = coneCapped([0, 0, 0.425], [0, 0, 3.225], 1.544, 1.201);
  bore = max(r - 0.625, -1.575 - p.z);
  return max(min(slots, wings, flange, shank), -bore);
}

// The carbide: a quarter-inch plate on each wing's seat, proud of the steel by 60 thou.
toothShort() {
  edge = max(dot(p.xz, [-0.3746, -0.927]) - 2.402, dot(p.xz, [0.3423, -0.9396]) - 3.725);
  return max(-p.y, p.y - 0.25, p.z + 2.36, 0.94 - p.x, length(p.xy) - 2.40, edge);
}

toothLong() {
  edge = max(dot(p.yz, [-0.3067, -0.9518]) - 2.595, dot(p.yz, [0.3427, -0.9394]) - 3.737);
  return max(p.x, -0.25 - p.x, p.z + 2.36, 0.38 - p.y, length(p.xy) - 2.40, edge);
}

teethInches() {
  pair = min(toothShort(), toothLong());
  return min(pair, remap(pair, [-p.x, -p.y, p.z]));
}

// ── The warp ──
// How far the bit bows, as a curvature for map.bendXZ: far more than life, so it reads.
// The bit's ends lean up to 7 degrees.
warpCurvature = 1 / 800.0;

// ── The library's labelled sprue, one value at a time ──
// These are only read for colour. Each returns one field, because a function
// that returns two must not be remapped: the viewer's shader then compiles
// the whole font in and reads the sprue's fields at the wrong point.
plainSprue() {
  body, holes = sprue.plain(sprueLength);
  return body;
}
labeledSprue() {
  body, holes = sprue.labeled(sprueLength, "S4340-T010", "S4340");
  return body;
}

// ── The whole scene, written out at treeAt, the point in the tree's own frame ──
treeAt = map.rotateXY(p, pi / 4) + treeCenter;

// Fold the branch round the sprue. The copies fan out of the one that was
// there, and the fold's seam stays in the gap behind them, so it cuts none.
around = atan(treeAt.y, treeAt.x) - fanStart - fanCenter;
fanAngle = around - 2 * pi * round(around / (2 * pi)) + fanCenter;
copyIndex = clamp(round(fanAngle / max(wedge, 0.001)), firstCopy, firstCopy + 3);
turn = copyIndex * wedge + fanStart;
branchAt = [treeAt.x * cos(turn) + treeAt.y * sin(turn), treeAt.y * cos(turn) - treeAt.x * sin(turn), treeAt.z + branchDrop];

// Once sawn, the sprue, what is left of the gates and three of the four parts come away together: up, and gone.
// The fold ends in the same instant they go, which leaves the one part that stays.
other = (abs(copyIndex) > 0.5 ? 1 : 0) * spread;
away = 1 - 0.9 * lifted;
feedAt = [treeAt.x / away, treeAt.y / away, 20 + (treeAt.z - 150 * lifted - 20) / away];
feedBranchAt = [branchAt.x / away, branchAt.y / away, feedAt.z + branchDrop];
gone = (lifted > 0.995 ? 1000 : 0);

// While the others leave, their wedges of the fold must still know the part that stays is there,
// or a ray crossing one would step straight through it. A cylinder round that part, which lies
// wholly inside its own wedge, is bound enough.
keptRadius = 70.0;
keptAt = [treeAt.x * cos(fanStart) + treeAt.y * sin(fanStart) - treeRadius, treeAt.y * cos(fanStart) - treeAt.x * sin(fanStart)];
keptGuard = length(keptAt) - keptRadius + 1000 * (1 - other * (lifted > 0 ? 1 : 0));

// The warp: the bit as a plate standing between its two gates, bent to an arc in the plane
// through the sprue's axis. Its belly is toward the sprue when the curvature is positive and
// away when negative. The gates flex with it: fixed at the sprue, and carried along with the bit
// where they meet it. Where the bend squeezes space the field is scaled down to stay a distance.
partAt = branchAt + (feedBranchAt - branchAt) * other;
plateAt = [treeRadius, 0, 0];
bow = warp * warpCurvature;
bowedAt = map.bendXZ(partAt - plateAt, bow) + plateAt;
squeeze = min(1, length([1 - bow * (partAt.x - plateAt.x), bow * partAt.z]));
gateFlex = (bowedAt - partAt) * ease.quadratic(clamp((partAt.x - sprue.shaftRadius) / joggleLength, 0, 1));

// The bit, in its own frame.
bitAt = map.rotateAxis(bowedAt - partCenter, vector.zero, heroAxis, -heroAngle);
blank = remap(blankInches(), bitAt / (inch * shrink)) * inch * shrink * (1 + (away - 1) * other) * squeeze;

// Its carbide slides down the axis onto the seats, and a fillet of braze holds it there:
// what a rounded union of the tooth and the steel adds to the sharp one, and nothing of either.
// A skin is taken off the fillet so it ends at a toe a little way along each surface, instead of
// feathering out to nothing across the carbide; outside its toes there is no braze.
seated = 1 - teethOff + teethOn;
brazed = 1 - unbrazed + rebrazed;
tooth = remap(teethInches(), (bitAt + [0, 0, 70 * (1 - seated)]) / inch) * inch;
carbideAt = tooth + 4 * (1 - clamp(seated * 8, 0, 1)) + (seated < 0.001 ? 1000 : 0);
brazeRadius = 1.5 * brazed + 0.01;
brazeSkin = 0.08 * brazeRadius;
brazeToe = brazeRadius - sqrt(brazeSkin * (2 * brazeRadius + brazeSkin));
brazeAt = max(unionRound(blank, tooth, brazeRadius) + brazeSkin, max(blank, tooth) - brazeToe, -blank, -tooth)
  + (brazed < 0.001 ? 1000 : 0);

// There are no gates at all until the sprue is fully formed; then they grow out
// from its shaft. The saw crosses both on one plane, and
// leaves a stub of each on the part, which is then worn back to the part's own offsets.
reach = mix(sprue.shaftRadius - 6, 92, gatesIn);
ungated = gatesIn < 0.001 ? 1000 : 0;
gateBars = remap(branchGates(), branchAt + gateFlex);
stubDepth = stubReach * (1 - ground);
stub = max(gateBars, cutPlane - branchAt.x, branchAt.x - reach, blank - stubDepth) + 1000 * other + ungated;
runners = max(remap(branchGates(), feedBranchAt + gateFlex), feedBranchAt.x - min(cutPlane - 3 * sawn + 200 * other, reach)) + ungated;

// The sprue: a plain cylinder first, then the real one, solid: no mounting hole and no vents yet.
barStock = max(length(feedAt.xy) - sprue.shaftRadius * sprueIn, feedAt.z - sprue.topZ, -sprueLength - feedAt.z);
sprueNow = mix(barStock, remap(sprue.solid(sprueLength), feedAt), cupped);
feed = unionRound(runners, sprueNow, sprue.gateBlendRadius) * away + gone + (sprueIn < 0.005 ? 1000 : 0);

parts = min(blank, stub);
tree = min(parts, feed, keptGuard);

// The pour: a ball of steel above the cup, shrinking as it runs down the sprue,
// and a level that rises through the whole tree under a rippling surface.
level = mix(treeLow, pourTop, filled) + 1000 * (1 - poured);
ripple = 2.5 * rippling * sin(2 * pi * (length(treeAt.xy) / 90 - time / 1.3));
surface = treeAt.z - level - ripple;
ladleAt = [0, 0, sprue.topZ + 46];
ladleRadius = 38 * ladled * pow(1 - filled, 0.3333);
stream = max(length(treeAt.xy) - 6 * clamp(filled * 20, 0, 1) * clamp((1 - filled) * 6, 0, 1), treeAt.z - ladleAt.z, level - 5 - treeAt.z);
pouring = unionRound(length(treeAt - ladleAt) - ladleRadius, stream + (filled < 0.001 ? 1000 : 0), 6 * ladled + 0.01)
  + (filled > 0.999 ? 1000 : 0) + (ladled < 0.001 ? 1000 : 0) + 1000 * (1 - poured);

// The steel: the design until it is printed, then nothing until the pour, then the casting.
solidAt = unionRound(intersectRound(tree, surface, 4), pouring, 5) + 1000 * printing * (1 - poured);

// One Voronoi pattern, at two sizes: half size to eat the print, full size to crack and shed the shell.
cell = mix(shardSize / 2, shardSize, after(13, 0));
walls = remap(noise.cellularEdges(cell), treeAt) / 2;
burnFront = clamp(burned * 1.3 - 0.3 * (treeHigh - treeAt.z) / (treeHigh - treeLow), 0, 1);
shedFront = clamp((shed * (treeHigh - treeLow + 60) - (treeHigh - treeAt.z)) / 60, 0, 1);

// The printed pattern: the same tree with the mounting hole and the vents cut,
// hollowed to a skin over the sprue library's lattice. It arrives by turning
// into itself: the solid design and the printed one, mixed.
skinned = max(tree, -remap(sprue.mountHole(), feedAt));
struts = remap(sprue.latticeField(), treeAt);
pattern = max(mix(tree, max(skinned, -remap(sprue.vents(), feedAt)), printed), -sprue.latticeCavity(skinned, struts));
printAt = max(pattern, burnFront * cell * 0.75 - 0.5 - walls)
  + 1000 * (1 - printing) + (burned > 0.999 ? 1000 : 0);

// The shell: the tree, offset, coat by coat. It stops below the cup's rim, where its edge is
// rounded into the capping plane, and it is cut open toward the camera.
viewCut = -treeAt.y - mix(170, treeRadius / sqrt2, sectioned);   // from just clear of the shell to the two front bits' axes
shellWall = max(tree - shellThickness * coats, 0.05 - tree);
shellAt = max(intersectRound(shellWall, treeAt.z - shellTop, 3 * coats + 0.01), viewCut,
              cracked * 0.35 + shedFront * cell * 0.7 - 0.05 - walls)
  + (coats < 0.001 ? 1000 : 0) + (shed > 0.999 ? 1000 : 0);

steel = solidAt;
print = printAt;
shell = shellAt;
carbide = carbideAt;
braze = brazeAt;

scene = [[-340, -340, -300], [340, 340, 340]];
steel.box = scene;
print.box = scene;
shell.box = scene;
carbide.box = scene;
braze.box = scene;

// ── Colour and heat: none of this is in the ray march ──

// How a hot body looks at a temperature, as a colour and a strength the screen can show:
// dull red at 600 C, orange at 1000, yellow-white where steel pours at 1600.
heatColor(celsius) {
  t = clamp((celsius - 550) / 1000, 0, 1);
  return [1, 0.12 + 0.83 * t * t, 0.02 + 0.65 * t * t * t];
}
heatStrength(celsius) { return clamp((celsius - 520) / 650, 0, 1.6); }

// heated(material, celsius): the same surface, glowing as hot as it is. The steel, the shell and the braze all wear it.
heated(m, celsius) {
  return material.blend(m, material.glowing(heatColor(celsius), heatStrength(celsius)), clamp(heatStrength(celsius), 0, 1));
}

// A colour between two colours. (The builtin mix, given vectors here, fails to build for the viewer.)
tint(from, to, t) { return from + (to - from) * t; }

steelGray = [0.70, 0.71, 0.72];
designGray = [0.50, 0.54, 0.60];     // the design: one plain steel for part, sprue and gates, not the finished bit's
asCast = [0.30, 0.29, 0.28];
cutSteel = [0.82, 0.83, 0.85];
resin = [0.96, 0.78, 0.38];

// Shot peening: a dimple about a millimetre across, one per cell of a small cellular pattern that rides on the bit.
dimpleSize = 0.9;
dimples = remap(noise.cellular(dimpleSize), bitAt) / dimpleSize;
// Where a dimple is too small for the screen to show, it fades to the average shade rather than shimmering.
peenedColor = steelGray * (0.93 + 0.16 * (dimples - 0.45) * texture.fadeDetail(dimpleSize));

// The labels: the sprue library's own engraving, read here as ink where it would cut the surface.
onFeed = feed < parts ? 1 : 0;
inked = onFeed * labelled * (remap(labeledSprue(), feedAt) - remap(plainSprue(), feedAt) > 0.06 ? 1 : 0);
designed = turned;                  // the finished bit becomes the design as it is turned
designColor = tint(tint(tint(peenedColor, designGray, designed), designGray, onFeed), [0.06, 0.06, 0.10], inked);

// Where the saw and then the grinding have been: bright steel, with the grinding's lay.
cutFace = (sawn > 0.5 ? 1 : 0) * (gateBars < 0.4 ? 1 : 0) * (1 - onFeed)
  * (abs(blank - stubDepth) < 0.6 ? 1 : (abs(branchAt.x - cutPlane) < 0.6 ? 1 : 0));
// As cast, the steel is dark with oxide, blotched a hand's width across.
scaleTone = asCast * (0.85 + 0.3 * clamp(0.5 + 0.5 * remap(noise.gradient(22), treeAt), 0, 1));
castColor = tint(tint(scaleTone, cutSteel, cutFace), peenedColor, peened);

// Cooling follows Newton's law: the heat still to lose falls by the same share every second, so
// it goes fast at first and ever slower. The steel loses 1/e of it in steelCoolingSeconds, which
// puts out its glow, at about 520 C, six and a half seconds in; the shell's enclosed middle,
// which cannot see out, takes longer.
ambientCelsius = 30;
pourCelsius = 1600;
furnaceCelsius = 950;
brazingCelsius = 1150;
steelCoolingSeconds = 5.6;

// The steel is hot from the pour, and hot again where the inserts are brazed on. There the heat
// starts as a thin hot line along each seat and soaks into the steel as heat does, a distance
// that grows with the root of the time since the torch came on. How far a point is from a seat
// is the insert's own distance field.
steelDiffusivity = 12.0;            // mm2/s, about an alloy steel's
heatReach = sqrt(4 * steelDiffusivity * torchSeconds) + 0.3;
nearTooth = exp(-(max(tooth, 0) / heatReach) * (max(tooth, 0) / heatReach));
castCelsius = ambientCelsius + (pourCelsius - ambientCelsius) * exp(-coolingSeconds / steelCoolingSeconds);
steelCelsius = mix(ambientCelsius, max(castCelsius, ambientCelsius + (brazingCelsius - ambientCelsius) * torched * nearTooth), poured);
steelHeat = clamp(heatStrength(steelCelsius), 0, 1);

// The bit is the same steel at the end as at the start: the casting takes its finish as it is peened.
finishedSteel = material.make(0.45, 0.9, 1.5);
designSteel = material.make(0.55, 0.7, 1.5);
castSteel = material.make(0.7, 1, 1.5);
groundSteel = material.withLay(material.make(0.3, 1, 1.5), [0, 0, 1], 0.8);   // the grinding's lay, as a streaked highlight
castNow = material.blend(material.blend(castSteel, groundSteel, cutFace), finishedSteel, peened);
steelNow = material.blend(material.blend(finishedSteel, designSteel, designed), castNow, poured);
// The analysis: while the body is studied, patches of it light up and die away at random, in its own colour.
scan = clamp(remap(noise.gradient4(16, 0.9), bitAt) * 2.6 - 0.3, 0, 1) * analysing;
