steel.material = heated(material.blend(steelNow, material.glowing(steelGray, 2.5), 0.9 * scan), steelCelsius);

// The print turns from the design's steel into clear resin as it turns into the pattern.
print.color = tint(designColor, resin, printed);
print.material = material.blend(designSteel, material.translucent(material.make(0.25, 0, 1.5), 0.8, 40), printed);

// The shell is fired while the print burns out, evenly, as a furnace soaks it, so it is already
// glowing when the metal arrives. The metal heats it further, a little ahead of its own level,
// so the top of the shell is hot too once the tree is full. Then it cools as the steel does,
// the middle of the tree last.
reached = poured * clamp((level + 15 - treeAt.z) / 15, 0, 1);
enclosed = 1 - clamp(length(treeAt.xy) / 150, 0, 1);
shellHot = ambientCelsius + (furnaceCelsius + 50 * enclosed - ambientCelsius) * burned + 250 * reached;
shellCelsius = ambientCelsius + (shellHot - ambientCelsius) * exp(-coolingSeconds / (steelCoolingSeconds * (1 + 0.6 * enclosed)));
shellHeat = clamp(heatStrength(shellCelsius), 0, 1);
// The ceramic is a stucco: an uneven cream, a little darker where the slurry ran thick.
stucco = [0.93, 0.91, 0.85] * (0.95 + 0.07 * clamp(0.5 + 0.5 * remap(noise.gradient(30), treeAt), 0, 1));
shell.color = stucco * (1 - 0.85 * shellHeat);
shell.material = heated(material.make(0.95, 0, 1.5), shellCelsius);

// Brazing: the teeth and the steel round them are brought up to heat, the braze runs in, and it all cools.
brazeCelsius = ambientCelsius + (brazingCelsius - ambientCelsius) * torched;
torchHeat = clamp(heatStrength(brazeCelsius), 0, 1);
carbide.color = [0.20, 0.21, 0.23] * (1 - 0.8 * torchHeat);
carbide.material = heated(material.make(0.35, 1, 1.5), brazeCelsius);

// The braze: a brass-coloured fillet, laid down hot at the end.
braze.color = [0.83, 0.62, 0.24] * (1 - 0.8 * torchHeat);
braze.material = heated(material.make(0.3, 1, 1.5), brazeCelsius);

return steel, print, shell, carbide, braze;

