fn gate_horizontalRound(p: vec3<f32>, pos: vec3<f32>, width: f32, height: f32, gatePenetration: f32, noiseTex: texture_3d<f32>) -> f32 {
  let center = vec3<f32>(pos.x * 0.5 + gatePenetration * 0.5, pos.y, pos.z);
  let fillet = min(width, height) * 0.5;
  let dy = abs(p.y - center.y) - (width * 0.5 - fillet);
  let dz = abs(p.z - center.z) - (height * 0.5 - fillet);
