fn ease_inQuadratic(t: f32, noiseTex: texture_3d<f32>) -> f32 {
  return t * t;
}

fn ease_outQuadratic(t: f32, noiseTex: texture_3d<f32>) -> f32 {
  return 1.0 - ease_inQuadratic(1.0 - t, noiseTex);
}

fn ease_quadratic(t: f32, noiseTex: texture_3d<f32>) -> f32 {
  return t * t * (3.0 - 2.0 * t);
